import csv
import io
import unittest
from exporter import export_rows

def parse_csv(output):
    return list(csv.reader(io.StringIO(output)))

class ExportTests(unittest.TestCase):
    def test_header(self):
        self.assertEqual(parse_csv(export_rows([]))[0], ["customer_id", "region"])

    def test_missing_region_key_is_na(self):
        rows = [{"customer_id": "0001"}]
        body = parse_csv(export_rows(rows))[1:]
        self.assertEqual(body, [["0001", "NA"]])

    def test_none_region_is_na(self):
        rows = [{"customer_id": "0002", "region": None}]
        body = parse_csv(export_rows(rows))[1:]
        self.assertEqual(body, [["0002", "NA"]])

    def test_empty_string_region_stays_empty(self):
        rows = [{"customer_id": "0003", "region": ""}]
        body = parse_csv(export_rows(rows))[1:]
        self.assertEqual(body, [["0003", ""]])

    def test_present_region_unchanged(self):
        rows = [{"customer_id": "0004", "region": "US"}]
        body = parse_csv(export_rows(rows))[1:]
        self.assertEqual(body, [["0004", "US"]])

    def test_customer_id_preserved_with_leading_zeros(self):
        rows = [{"customer_id": "00012", "region": "CA"}]
        body = parse_csv(export_rows(rows))[1:]
        self.assertEqual(body, [["00012", "CA"]])

if __name__ == "__main__":
    unittest.main()

